float n_uv_value = (In.UV).x;
float n_ramp_factor = saturate(n_uv_value);
float n_ramp_stop_0 = saturate(0f);
float4 n_ramp_stop_color_0 = float4(0f, 0f, 0f, 1f);
float n_ramp_stop_1 = saturate(0.5f);
float4 n_ramp_stop_color_1 = float4(1f, 0f, 0f, 0.200000003f);
float n_ramp_stop_2 = saturate(0.5f);
float4 n_ramp_stop_color_2 = float4(0f, 1f, 0f, 0.800000012f);
float n_ramp_stop_3 = saturate(1f);
float4 n_ramp_stop_color_3 = float4(1f, 0.5f, 0.25f, 1f);
float4 n_ramp_color = n_ramp_stop_color_0;
float n_ramp_t_1 = saturate((n_ramp_factor - n_ramp_stop_0) / max(n_ramp_stop_1 - n_ramp_stop_0, 1e-5f));
if (n_ramp_factor >= n_ramp_stop_0 && n_ramp_factor < n_ramp_stop_1) n_ramp_color = lerp(n_ramp_stop_color_0, n_ramp_stop_color_1, n_ramp_t_1);
float n_ramp_t_2 = saturate((n_ramp_factor - n_ramp_stop_1) / max(n_ramp_stop_2 - n_ramp_stop_1, 1e-5f));
if (n_ramp_factor >= n_ramp_stop_1 && n_ramp_factor < n_ramp_stop_2) n_ramp_color = lerp(n_ramp_stop_color_1, n_ramp_stop_color_2, n_ramp_t_2);
float n_ramp_t_3 = saturate((n_ramp_factor - n_ramp_stop_2) / max(n_ramp_stop_3 - n_ramp_stop_2, 1e-5f));
if (n_ramp_factor >= n_ramp_stop_2 && n_ramp_factor < n_ramp_stop_3) n_ramp_color = lerp(n_ramp_stop_color_2, n_ramp_stop_color_3, n_ramp_t_3);
if (n_ramp_factor >= n_ramp_stop_3) n_ramp_color = n_ramp_stop_color_3;
float n_ramp_alpha = n_ramp_color.a;
return n_ramp_color;
